contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient, uint256 amount) public payable {
        // fund this test contract, then deposit into c
        require(address(this).balance >= amount);
        c.fallback{value: amount}();

        uint256 beforeBal = address(c).balance;
        uint256 recipientBefore = recipient.balance;

        bool reverted;
        bool ownerCall = (caller == c.owner());
        if (ownerCall) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert((ownerCall && !reverted && address(c).balance == 0 && recipient.balance == recipientBefore + beforeBal) || (!ownerCall && reverted && address(c).balance == beforeBal && recipient.balance == recipientBefore));
    }

    receive() external payable {}
}

