        assert((caller == c.owner() && !reverted && address(c).balance == 0 && recipient.balance == recipientBefore + beforeBal) || (caller != c.owner() && reverted && address(c).balance == beforeBal && recipient.balance == recipientBefore));
    }

    receive() external payable {}
}

