contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient) public {
        require(caller != address(0));
        uint256 balBefore = address(c).balance;
        bool reverted;
        if (caller == c.owner()) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
